use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,fmt::Write,path::{Path,PathBuf},process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-native-buckets176";const O:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-g2-native-buckets176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn walk(p:&Path)->Vec<PathBuf>{let mut out=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){out.extend(walk(&p));}else if p.is_file(){out.push(p);}}out.sort();out}
fn allowed(p:&Path)->bool{matches!(p.extension().and_then(|s|s.to_str()),Some("rs"|"md"|"json"|"log"|"csv"|"toml"|"lock"))}
fn gzip(p:&Path,bytes:&[u8]){let tmp=p.with_extension("temporary");fs::write(&tmp,bytes).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&tmp).stdout(Stdio::from(fs::File::create(p).unwrap())).status().unwrap().success());let decoded=Command::new("gzip").args(["-d","-c"]).arg(p).output().unwrap();assert!(decoded.status.success());assert_eq!(decoded.stdout,bytes);fs::remove_file(tmp).unwrap();}
fn main(){let review=read(r("review.json"));assert_eq!(review["passed"],true);assert_eq!(review["gate_passed"],false);let a=read(r("analysis.json"));let mut batches=0u64;let mut profile_samples=0;
for(name,v)in a["caller_receipts"].as_object().unwrap(){batches+=(v["rounds_per_worker"].as_u64().unwrap()+384)*v["workers"].as_u64().unwrap();if name.starts_with("cycles-"){let pid=v["pid"].as_u64().unwrap();let cpus=v["worker_rows"].as_array().unwrap().iter().map(|w|(w["tid"].as_u64().unwrap(),w["cpu"].as_u64().unwrap())).collect::<BTreeMap<_,_>>();for line in fs::read_to_string(r(format!("runs/decode-{name}/stdout.log"))).unwrap().lines().filter(|l|!l.starts_with('#')&&!l.trim().is_empty()){let f=line.split_whitespace().collect::<Vec<_>>();let ids=f[0].split('/').map(|s|s.parse::<u64>().unwrap()).collect::<Vec<_>>();assert_eq!(ids[0],pid);let cpu=f[1].trim_matches(['[',']']).parse::<u64>().unwrap();if ids[1]!=pid{assert_eq!(cpus[&ids[1]],cpu);}assert!(cpu<32);profile_samples+=1;}}}
assert_eq!(batches,45708864);assert_eq!(profile_samples,70278);
let out=Path::new(O);assert!(!out.exists());fs::create_dir_all(out.join("artifacts")).unwrap();let mut source=BTreeMap::new();for p in walk(&r("source")){let b=fs::read(&p).unwrap();let hex=b.iter().map(|v|format!("{v:02x}")).collect::<String>();let restored=hex.as_bytes().chunks_exact(2).map(|s|u8::from_str_radix(std::str::from_utf8(s).unwrap(),16).unwrap()).collect::<Vec<_>>();assert_eq!(restored,b);source.insert(p.strip_prefix(r("source")).unwrap().display().to_string(),json!({"hex":hex,"length":b.len(),"sha256":hash(&b)}));}assert_eq!(source.len(),178);gzip(&out.join("artifacts/source178.json.gz"),&serde_json::to_vec(&source).unwrap());
let mut files=fs::read_dir(R).unwrap().map(|e|e.unwrap().path()).filter(|p|p.is_file()&&allowed(p)).collect::<Vec<_>>();for d in["driver","native","runs","stat"]{files.extend(walk(&r(d)).into_iter().filter(|p|allowed(p)));}let mut receipts=BTreeMap::new();for p in files{let b=fs::read(&p).unwrap();let text=String::from_utf8(b.clone()).unwrap();assert_eq!(text.as_bytes(),b);receipts.insert(p.display().to_string(),json!({"utf8":text,"length":b.len(),"sha256":hash(&b)}));}let encoded=serde_json::to_vec(&receipts).unwrap();let decoded:Value=serde_json::from_slice(&encoded).unwrap();for(_,v)in decoded.as_object().unwrap(){let b=v["utf8"].as_str().unwrap().as_bytes();assert_eq!(hash(b),v["sha256"]);assert_eq!(b.len(),v["length"].as_u64().unwrap()as usize);}gzip(&out.join("artifacts/receipts-and-helpers.json.gz"),&encoded);
for size in[200,352]{for arm in["frozen","OFF","ON"]{let n=format!("cycles-G2-{size}-w32-{arm}.data");gzip(&out.join("artifacts").join(format!("{n}.gz")),&fs::read(r("perf").join(n)).unwrap());}}
for f in["analysis.json","review.json","source-audit.json","work-audit.json","identities.json","design.md","protocol.md","native-state.rs","native-apply.rs","store.rs","tests.rs","setup.rs","prepare-build.rs","campaign.rs","campaign-analysis.rs","review.rs","publish.rs","offline-failures.json","analysis-initial-failure.json","setup-initial-failure.json"]{fs::copy(r(f),out.join("artifacts").join(f)).unwrap();}fs::copy(r("report-draft.md"),out.join("README.md")).unwrap();
let publication=json!({"source_members":178,"receipt_members":receipts.len(),"raw_profiles":6,"gzip_roundtrip_verified":true,"source_hex_roundtrip_verified":true,"UTF8_member_hashes_verified":true,"all_profile_worker_TID_CPU_bindings_rechecked":true,"profile_samples_rechecked":profile_samples,"batch_calls_including_primes":batches,"private_arrays_or_executables_published":false});fs::write(out.join("artifacts/publication.json"),serde_json::to_vec_pretty(&publication).unwrap()).unwrap();let mut sums=String::new();let files=walk(out);for p in&files{writeln!(sums,"{}  {}",hash(&fs::read(p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("{}",json!({"published_files":files.len()+1,"publication":publication}));}
